{
  "name": "连续运动扫描控制组件",
  "name_en": "Slew Scan Control Component",
  "manufacturer": "",
  "description": "一个非物理的软件扫描组件，用于实验中的连续运动（slew）扫描流程控制。它负责准备扫描、检查光束状态、协调轨迹运动与探测器触发/等待，并将主文件、MCS、环境数据及额外探测器数据写入保存。",
  "description_en": "A non-physical software scan component used to control continuous-motion (slew) scan workflows in experiments. It prepares scans, checks beam status, coordinates trajectory motion and detector arming/waiting, and saves master, MCS, environmental, and extra detector data.",
  "actions": [
    {
      "action_name": "auto-check_beam_ok",
      "description": "检查光束状态是否适合继续扫描。",
      "description_en": "Check whether the beam status is suitable for continuing the scan."
    },
    {
      "action_name": "auto-post_slew_scan",
      "description": "执行连续扫描结束后的收尾处理。",
      "description_en": "Perform post-processing and cleanup after a slew scan."
    },
    {
      "action_name": "auto-prepare_scan",
      "description": "准备连续运动扫描流程。",
      "description_en": "Prepare the continuous-motion scan workflow."
    },
    {
      "action_name": "auto-run",
      "description": "运行连续运动扫描，并协调运动、探测器与数据保存。",
      "description_en": "Run the continuous-motion scan, coordinating motion, detectors, and data saving."
    },
    {
      "action_name": "auto-save_envdata",
      "description": "保存实验环境数据。",
      "description_en": "Save experimental environmental data."
    },
    {
      "action_name": "auto-save_extra_data",
      "description": "保存额外探测器数据，如 XRF 或 XRD 数据。",
      "description_en": "Save extra detector data, such as XRF or XRD data."
    },
    {
      "action_name": "auto-save_mcs_data",
      "description": "保存 MCS 多道标量器数据。",
      "description_en": "Save MCS multichannel scaler data."
    },
    {
      "action_name": "auto-write_master",
      "description": "将文本行写入主数据文件。",
      "description_en": "Write text lines to the master data file."
    }
  ],
  "tag_hints": [
    "slew scan",
    "continuous motion scanning",
    "scan workflow orchestration",
    "detector synchronization",
    "trajectory scan control",
    "beamline automation",
    "MCS data logging",
    "environment data saving"
  ]
}

